import json, sys, unicodedata
rows=json.load(sys.stdin)
results=[]
for row in rows:
    try:
        with open(sys.argv[1] + '/' + row['file'], encoding='utf-8', errors=row['errors'], newline=row['newline']) as stream:
            result={'points':list(map(ord,stream.read()))}
    except UnicodeDecodeError as error:
        result={'error':[type(error).__name__,error.encoding,list(error.object),error.start,error.end,error.reason]}
    results.append(result)
print(json.dumps({'target':{'version':sys.version,'unicode':unicodedata.unidata_version,'platform':sys.platform,'byteorder':sys.byteorder},'results':results}))
